    if bin_residual == bin_capacity {
        let expected_fill = if total_items > 0 {
            (total_items as f64 * item_size as f64 / open_bins_count.max(1) as f64).min(bin_capacity as f64)
        } else {
            item_size as f64
        };
        let capacity_penalty = 16.0 + 0.10 * (bin_capacity as f64 - expected_fill);
        let scarcity = if fitting_bins_count == 0 {
            9.0
        } else {
            0.0
        };
        score += capacity_penalty + scarcity;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size.max(1) as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Base preference for a tight, reusable placement.
    let mut score = post;

    // Compare the remaining space with the next item's likely demand.
    let lookahead = next.max(item * 0.85);
    if post > 0.0 && post < lookahead {
        let deficit = lookahead - post;
        let deficit_ratio = (deficit / lookahead).min(1.0);
        score += 0.9 * deficit + 0.06 * deficit * deficit;
        score += 5.5 * deficit_ratio * deficit_ratio;
    }

    // Prefer residual space near the stream's average, but avoid wasting a bin.
    let residual_mismatch = (residual - mean_residual).abs();
    score += 0.028 * residual_mismatch;

    let fill_ratio = (residual / capacity).min(1.0);
    let target_ratio = (item / capacity).min(1.0);
    score -= 0.74 * (fill_ratio - target_ratio).abs();

    // A nearly full bin is valuable, while a completely full one is excellent.
    if post <= 0.5 {
        score -= 9.0;
    } else if post < item * 0.12 {
        score -= 1.4;
    }

    // Reward enough room for the immediate successor, with diminishing value.
    if next > 0.0 && post >= next {
        let reusable_slack = post - next;
        score -= 3.2 + 0.8 * reusable_slack.min(item);
        if post >= next + item {
            score -= 0.7;
        }
    }

    // Consolidate when there are few alternatives; accept poor fits only if forced.
    let poor_fit = post < item * 0.48 || residual > item * 1.9;
    if fitting_bins_count <= 1 {
        score -= 4.8 + 2.2 * progress;
    } else if poor_fit && fitting_bins_count <= 3 {
        score += 1.9 * (fitting_bins_count as f64 - 1.0);
    }

    // An empty bin must compete against the best existing residual.
    if bin_residual == bin_capacity {
        score += 13.0 + 10.0 * progress;
        score -= 4.0 * (1.0 - progress);

        if fitting_bins_count == 0 {
            score -= 9.0;
        } else if fitting_bins_count <= 2 {
            score -= 2.2;
        }
    }

    // Penalize excessive simultaneous capacity, especially late in the stream.
    score += 0.010 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size.max(1) as f64;
    let pressure = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let mut score = post;

    // Penalize unusable slack more sharply as the residual becomes fragmented.
    let near_need = next.min(item.max(next));
    if post > 0.0 && post < near_need {
        let deficit = near_need - post;
        score += 0.75 * deficit + 0.045 * deficit * deficit;
    }

    // Dead space should be discounted when it can plausibly be reused.
    let dead_space = post.max(0.0);
    if dead_space > 0.0 && dead_space < near_need {
        let dead_ratio = dead_space / near_need;
        score += (1.0 - dead_ratio) * (4.0 + 5.0 * pressure);
    }

    // Favor residuals near the stream's typical residual, but gently.
    let residual_mismatch = (residual - mean_residual).abs();
    score += 0.035 * residual_mismatch;

    let fill_ratio = residual / capacity;
    let target_ratio = (item / capacity).min(1.0);
    score -= 0.62 * (fill_ratio - target_ratio).abs();

    if post <= 0.5 {
        score -= 7.5;
    }

    // Preserve enough room for the immediately following item.
    if next > 0.0 && post >= next {
        let reusable_slack = post - next;
        score -= 2.8 + 0.9 * reusable_slack.min(item);
    }

    // A new bin is attractive when current placements create a very poor fit.
    let poor_fit = post < item * 0.55 || residual > item * 1.65;
    if fitting_bins_count <= 1 {
        score -= 4.0 + 2.0 * pressure;
    } else if poor_fit && fitting_bins_count <= 3 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Account for a new empty bin separately from ordinary residuals.
    if bin_residual == bin_capacity {
        score += 12.0 + 9.0 * pressure;
        score -= 3.5 * (1.0 - pressure);

        // Opening early is justified only when alternatives are fragmented.
        if fitting_bins_count == 0 {
            score -= 8.0;
        } else if fitting_bins_count <= 2 {
            score -= 2.0;
        }
    }

    // Mildly prefer consolidation as the stream progresses.
    score += 0.012 * open_bins_count as f64 * pressure;

    score
}
